/* ---- Validation ---- */
SELECT 'carriers' AS table_name, COUNT(*) AS row_count FROM freight.carriers UNION ALL SELECT 'lanes', COUNT(*) FROM freight.lanes UNION ALL SELECT 'fuel_prices', COUNT(*) FROM freight.fuel_prices UNION ALL SELECT 'shipments', COUNT(*) FROM freight.shipments;
SELECT status, COUNT(*) AS shipments FROM freight.shipments GROUP BY status;
SELECT TOP 5 carrier_name, lane_name, shipments, on_time_rate FROM freight.v_carrier_lane_performance WHERE shipments >= 15 ORDER BY on_time_rate;
GO
